import { useState, useEffect, useContext } from "react";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";
import { Users, UserCheck, Settings, FileText, BarChart3, LogOut } from "lucide-react";

export default function AdminDashboard() {
  // ---------------- State (identical to your original) ----------------
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});

  const { logout, token, user } = useContext(AuthContext); // keep token & logout for behavior; user optional
  const navigate = useNavigate();

  // ---------------- Unified error handler (exact behavior preserved) ----------------
  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      alert(err.response?.data?.error || err.message);
    }
  };

  // ---------------- Backend API calls (unchanged) ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      handleApiError(err);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async () => {
    try {
      const res = await api.get("/admin/results");
      setResults(res.data.positionResults);
      setWinners(res.data.winners);
    } catch (err) {
      handleApiError(err);
    }
  };

  // ---------------- Initial load (preserved) ----------------
  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }

    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchResults();
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  // ---------------- UI (student-like cards, but all functionality inside) ----------------
  return (
    <div className="min-h-screen bg-gray-100">
      <div className="max-w-6xl mx-auto p-6">
        {/* Header */}
        <header className="flex items-center justify-between bg-white p-4 rounded-xl shadow mb-6">
          <div className="flex items-center gap-4">
            <img src="/logo.png" alt="iVote Logo" className="h-12 w-auto" />
            <div>
              <h1 className="text-2xl font-bold text-blue-600">
                Welcome, {user?.name || "Admin"}
              </h1>
              <p className="text-sm text-gray-500">Admin Dashboard</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={() => { logout(); navigate("/login"); }}
              className="flex items-center gap-2 bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg transition"
              title="Logout"
            >
              <LogOut size={16} /> Logout
            </button>
          </div>
        </header>

        {/* Status widgets */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
          <div className="bg-white p-4 rounded-xl border shadow-sm flex items-center gap-4">
            <Users size={36} className="text-blue-600" />
            <div>
              <p className="text-sm text-gray-500">Pending Users</p>
              <p className="text-xl font-semibold">{pendingUsers.length}</p>
            </div>
          </div>

          <div className="bg-white p-4 rounded-xl border shadow-sm flex items-center gap-4">
            <UserCheck size={36} className="text-green-600" />
            <div>
              <p className="text-sm text-gray-500">Candidates</p>
              <p className="text-xl font-semibold">{candidates.length}</p>
            </div>
          </div>

          <div className="bg-white p-4 rounded-xl border shadow-sm flex items-center gap-4">
            <Settings size={36} className={votingOpen ? "text-green-600" : "text-red-600"} />
            <div>
              <p className="text-sm text-gray-500">Voting Status</p>
              <p className="text-xl font-semibold">{votingOpen ? "Open" : "Closed"}</p>
            </div>
          </div>
        </div>

        {/* Action cards grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
          {/* Voting card - uses toggleVoting (unchanged) */}
          <div className="bg-white p-6 rounded-xl border shadow-sm">
            <div className="flex items-start gap-4">
              <Settings size={36} className={votingOpen ? "text-green-600" : "text-red-600"} />
              <div className="flex-1">
                <h2 className="text-lg font-semibold text-gray-800">Voting Status</h2>
                <p className="text-sm text-gray-500 mt-1">
                  The voting system is currently <span className={votingOpen ? "text-green-600 font-medium" : "text-red-600 font-medium"}>{votingOpen ? "Open" : "Closed"}</span>.
                </p>
              </div>
              <div>
                <button
                  onClick={toggleVoting}
                  className={`px-4 py-2 rounded-lg text-white font-medium ${votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"}`}
                >
                  {votingOpen ? "Close Voting" : "Open Voting"}
                </button>
              </div>
            </div>
          </div>

          {/* Pending Users card - lists pendingUsers and uses approve/reject (unchanged) */}
          <div className="bg-white p-6 rounded-xl border shadow-sm">
            <div className="flex items-start gap-4 mb-4">
              <Users size={36} className="text-blue-600" />
              <div className="flex-1">
                <h2 className="text-lg font-semibold text-gray-800">Pending Voter Registrations</h2>
                <p className="text-sm text-gray-500 mt-1">Approve or reject pending registrations.</p>
              </div>
            </div>

            {pendingUsers.length === 0 ? (
              <p className="text-gray-500 italic">No pending users.</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm border border-gray-200 rounded-lg">
                  <thead className="bg-gray-50 text-gray-700">
                    <tr>
                      <th className="px-4 py-2 text-left">Student Number</th>
                      <th className="px-4 py-2 text-left">Name</th>
                      <th className="px-4 py-2 text-left">Email</th>
                      <th className="px-4 py-2 text-center">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {pendingUsers.map((user) => (
                      <tr key={user.id} className="border-t hover:bg-gray-50">
                        <td className="px-4 py-2">{user.studentNumber}</td>
                        <td className="px-4 py-2">{user.name}</td>
                        <td className="px-4 py-2">{user.email}</td>
                        <td className="px-4 py-2 text-center space-x-2">
                          <button onClick={() => approveUser(user.id)} className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700">Approve</button>
                          <button onClick={() => rejectUser(user.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Reject</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Candidates card - lists candidates and uses deleteCandidate (unchanged) */}
          <div className="bg-white p-6 rounded-xl border shadow-sm">
            <div className="flex items-start gap-4 mb-4">
              <UserCheck size={36} className="text-green-600" />
              <div className="flex-1">
                <h2 className="text-lg font-semibold text-gray-800">Candidates</h2>
                <p className="text-sm text-gray-500 mt-1">Manage candidate list.</p>
              </div>
            </div>

            {candidates.length === 0 ? (
              <p className="text-gray-500 italic">No candidates found.</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm border border-gray-200 rounded-lg">
                  <thead className="bg-gray-50 text-gray-700">
                    <tr>
                      <th className="px-4 py-2 text-left">Name</th>
                      <th className="px-4 py-2 text-left">Position</th>
                      <th className="px-4 py-2 text-left">Party</th>
                      <th className="px-4 py-2 text-center">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {candidates.map((c) => (
                      <tr key={c.id} className="border-t hover:bg-gray-50">
                        <td className="px-4 py-2">{c.name}</td>
                        <td className="px-4 py-2">{c.position}</td>
                        <td className="px-4 py-2">{c.party || "-"}</td>
                        <td className="px-4 py-2 text-center">
                          <button onClick={() => deleteCandidate(c.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Delete</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Logs card - shows logs (unchanged) */}
          <div className="bg-white p-6 rounded-xl border shadow-sm">
            <div className="flex items-start gap-4 mb-4">
              <FileText size={36} className="text-indigo-600" />
              <div className="flex-1">
                <h2 className="text-lg font-semibold text-gray-800">System Logs</h2>
                <p className="text-sm text-gray-500 mt-1">Recent admin activity and audit trail.</p>
              </div>
            </div>

            {logs.length === 0 ? (
              <p className="text-gray-500 italic">No logs available.</p>
            ) : (
              <ul className="space-y-2 max-h-56 overflow-y-auto text-sm">
                {logs.map((log) => (
                  <li key={log.id} className="flex justify-between border-b pb-1 text-gray-700">
                    <span>{log.action}</span>
                    <span className="text-gray-400">{new Date(log.createdAt).toLocaleString()}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>

          {/* Results & Reports combined card (unchanged logic) */}
          <div className="bg-white p-6 rounded-xl border shadow-sm">
            <div className="flex items-start gap-4 mb-4">
              <BarChart3 size={36} className="text-teal-600" />
              <div className="flex-1">
                <h2 className="text-lg font-semibold text-gray-800">Election Results & Reports</h2>
                <p className="text-sm text-gray-500 mt-1">View results and generate cryptographic reports.</p>
              </div>
            </div>

            {/* Results */}
            <div className="mb-4">
              {Object.keys(results).length === 0 ? (
                <p className="text-gray-500 italic">No results available yet.</p>
              ) : (
                Object.keys(results).map((pos) => (
                  <div key={pos} className="mb-3">
                    <h3 className="font-medium text-gray-700">{pos}</h3>
                    <ul className="pl-4 text-sm">
                      {results[pos].map((c) => (
                        <li key={c.id}>
                          {c.name} — {c.votes} votes {winners[pos]?.id === c.id && <span className="text-green-600 font-semibold">(Winner)</span>}
                        </li>
                      ))}
                    </ul>
                  </div>
                ))
              )}
            </div>

            {/* Generate Report */}
            <div className="mt-2">
              <button
                onClick={generateReport}
                className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition"
              >
                Generate Final Report
              </button>

              {reportHash && (
                <p className="mt-3 text-gray-600 text-sm">
                  Cryptographic Hash: <span className="font-mono">{reportHash}</span>
                </p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
